export const zEnrollmentToken = z.object({
    token_id: zIdentifier,
    enrollment_token: zSecret,
    expires_at_unix_seconds: zUnixSeconds,
    enrollment_class: zEnrollmentClass,
    session_lifetime_seconds: z.int().gte(300).lte(86400).optional(),
    requested_name: zResourceName.optional(),
    enabled_capabilities: z.union([
        z.literal(8),
        z.literal(16),
        z.literal(24)
    ]).optional()
}).strict().refine((value) => value.enrollment_class === 'ephemeral'
    ? value.session_lifetime_seconds !== undefined
    : value.session_lifetime_seconds === undefined, 'session lifetime must match enrollment class');

export const zEnrollmentTokenRequest = z.object({
    network_id: zIdentifier,
    label: z.string().nullish().default('').refine((value) => value == null || trimmedBytes(value, 256, true), 'label must be trimmed and at most 256 UTF-8 bytes without NUL'),
    expires_at_unix_seconds: zUnixSeconds,
    enrollment_class: zEnrollmentClass.nullish(),
    session_lifetime_seconds: z.int().nullish(),
    requested_name: z.string().nullish().refine((value) => value == null || value === '' || trimmedBytes(value, 253), 'requested name must be empty or a valid resource name'),
    enabled_capabilities: z.union([
        z.literal(0),
        z.literal(8),
        z.literal(16),
        z.literal(24)
    ]).nullish()
}).strict().refine((value) => {
    const enrollmentClass = value.enrollment_class ?? 'durable';
    return enrollmentClass === 'ephemeral'
        ? value.session_lifetime_seconds != null && value.session_lifetime_seconds >= 300 && value.session_lifetime_seconds <= 86400
        : value.session_lifetime_seconds == null || value.session_lifetime_seconds === 0;
}, 'session lifetime must match enrollment class');

